@Observable final class Shell {                  // handler state, not a view registry
    var path = NavigationPath(); let model: Model   // which views exist, in order
    func open(_ screen: Screen) { path.append(screen) }        // switch
    func closeAll() { path.removeLast(path.count) }            // dispose the set
}
struct ShellView: View {
    @State private var shell = Shell(model: model)
    var body: some View {
        NavigationStack(path: $shell.path) {
            RootView(shell: shell)
                .navigationDestination(for: Screen.self) { ScreenView(screen: $0, model: shell.model) }
        }
    }
}

